#[test]
fn ghoulcallers_bell_mills_both_players() {
    let reg = registry();
    let mut state = game_at_step(Step::PrecombatMain, P0);

    let bell = named_creature(&mut state, &reg, "Ghoulcaller's Bell", P0);

